using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class GoreVidal
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "A narcissist is someone better looking than you are.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Congress no longer declares war or makes budgets. So that's the end of the constitution as a working machine.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Everybody likes a bit of gossip to some point, as long as it’s gossip with some point to it. That’s why I like history. History is nothing but gossip about the past, with the hope that it might be true.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I am at heart a propagandist, a tremendous hater, a tiresome nag, complacently positive that there is no human problem which could not be solved if people would simply do as I advise.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Well, the Constitution has not yet been pregnant.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "And though I rather suspect that in a century’s time the novel will be as rare and private an art form as poetry today or that delicate and laborious process by which dedicated men fire glass with color, it will always be worth the doing.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "If satire is to be effective, the audience must be aware of the things satirized; if they are not, the joke falls flat. Unfortunately for our native satirists, the American mass audience possess very little general information on any subject. Each individual knows his own immediate world, but as various research polls continually inform us, he holds little knowledge in common with others.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The size of the population of course has much to do with this collective ignorance. When Aristophanes made a satiric point, he could be confident that his audience would appreciate his slyest nuance because in a small community each citizen was bound to share with his fellows a certain amount of general information, literary, religious, and political. National units today are too large and, in America at least, education is too bland to hope for much change.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "After the script was ready there were the usual trials, delays, problems of temperament: each participant confident the others had gone into secret league to contrive his professional ruin (and on occasion cabals did flourish…the theater is a child’s world).", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I too feel hurt at the sort of reputation which hovers about my part of this venture. I cannot honestly make much of a case for myself. I played the game stolidly according to rules I abhor. But in extenuation I should like to say what many others have said before me: the theater and its writers are seriously, perhaps fatally, hampered by economic pressure. Because it costs too much to put on a play, one works in a state of hysteria. Everything is geared to success. Yet art is mostly failure. And it is only from a succession of daring, flawed works that the occasional masterwork comes. But in our theater to fail is death and the author of a play which fails is regarded with much the same sympathy as the murderer of a child.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Well, you know how one feels about history, the glamour of the past; I expected to hear everybody talking about great events—battles, poets, that kind of thing—but of course you don’t. You just squabble among yourselves.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "My dear, you must marry him too. I’m sure the three of you would make a lovely couple.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "War is your specialty. Historians love you for it. I love you for it. After all, not only is it fun, it’s creative! Your best scientific discoveries are made in wartime: the atom bomb, radar, luncheon meat. And think of all that travel! Getting away from home, making new acquaintances, indulging in amatory dalliance with strangers. So broadening. And then: the delirium of battle, the rush of adrenaline to the head as the trumpets sound ATTACK! Conrad, war is the principle art form of your race.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "There is something about a bureaucrat that does not like a poem.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "It is the spirit of the age to believe that any fact, however suspect, is superior to any imaginative exercise, no matter how true.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "One can never rely on the great keeping one's letters; and should those letters vanish, one is apt to be remembered only as the mysterious half of a dialogue to be reconstructed in the vaguest way from the surviving (and sometimes lesser!) half of the exchange.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Books always cost more in those cities where they are least read!", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "How marvelous books are, crossing worlds and centuries, defeating ignorance and, finally, cruel time itself.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "for ferocity there is nothing on Earth equal a Christian bishop hunting \"heresy\", as they call any opinion contrary to their own.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The folly of the clever is always more than that of the dull.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "In a good cause hypocrisy becomes a virtue.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Vengeance must end somewhere, and what better place to stop than at the prince?", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Constantinople has no past; only a noisy present and a splendid future, if the auguries are to be believed.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "They say to know oneself is to know all there is that is human. But of course no one can ever know himself. Nothing human is finally calculable; even to ourselves we are strange.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "It is one thing to use text to illustrate a point one is making, but quite another to quote merely to demonstrate the excellence of one's memory.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "By definition a bore is predictable. if you think you know in advance what a man is apt to say or do, you are not apt to be disagreeably surprised by him.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "because academics everywhere are forever attacking one another, and I had long since learned that one must never believe what a teacher says of another.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Despite all evidence to the contrary I do not believe humans innately cruel, but they fear change of any kind.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Are we a dream in the mind of a deity, or is each of us a separate dreamer, evoking his own reality?", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "No one can tell another man is true. Truth is all around us...Truth is where ever man has glimpsed divinity.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Modern Christianity is a encyclopedia of traditional superstition.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "His fault was a common one. He simply did not know what he was;he saw no flaw in himself, a not unusual blindness and preferable, on the whole , to being unable to find any virtue in oneself.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The rhetoric of hate is often most effective when couched in the idiom of love.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We are all so simple at heart that become unfathomable to one another.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The malice of a true Christian attempting to destroy an opponent is something unique in the world. No other religion ever considered it necessary to destroy others because they did not share the same beliefs. At worst, another man's belief might inspire amusement or contempt—the Egyptians and their animal gods, for instance. Yet those who worshipped the Bull did not try to murder those who worshipped the Snake, or to convert them by force from Snake to Bull. No evil ever entered the world quite so vividly or on such a vast scale as Christianity did.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Men are odd. If they cannot be first, they don't in the least mind being last.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We are all in the habit of censuring the great, as if we were popular playwrights, when in fact ordinary folk are quite as devious and as willful and as desperate to survive (if not prevail) as are thee great; particularly philosophers.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "On the throne of the world, any delusion becomes fact.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Traitors who prevail are patriots; usurpers who succeed are divine emperors.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "There is no terror equal that of the ignorant in a strange place.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "American writers want to be not good but great; and so are neither.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Whenever a friend succeeds, a little something in me dies.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I'm all for bringing back the birch, but only between consenting adults.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Envy is the central fact of American life.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "First coffee, then a bowel movement. Then the Muse joins me.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The hatred Americans have for their own government is pathological, if understandable. At one level it is simply thwarted greed: since our religion is making a buck, giving a part of that buck to any government is an act against nature.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "It is not enough to succeed. Others must fail.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I can understand companionship. I can understand bought sex in the afternoon, but I cannot understand the love affair.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "As one gets older, litigation replaces sex.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The theater needs continual reminders that there is nothing more debasing than the work of those who do well what is not worth doing at all.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "At any given moment, public opinion is a chaos of superstition, misinformation, and prejudice.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The more money an American accumulates the less interesting he himself becomes.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "In any case, rather like priests who have forgotten the meaning of the prayers they chant, we shall go on for quite a long time talking of books and writing books, pretending all the while not to notice that the church is empty and the parishioners have gone elsewhere to attend other gods, perhaps in silence or with new words.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "That peculiarly American religion, President-worship.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The period of Prohibition — called the noble experiment — brought on the greatest breakdown of law and order the United States has known until today. I think there is a lesson here. Do not regulate the private morals of people. Do not tell them what they can take or not take. Because if you do, they will become angry and antisocial and they will get what they want from criminals who are able to work in perfect freedom because they have paid off the police.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The United States was founded by the brightest people in the country — and we haven't seen them since.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Big oil, big steel, big agriculture avoid the open marketplace. Big corporations fix prices among themselves and thus drive out of business the small entrepreneur. Also, in their conglomerate form, the huge corporations have begun to challenge the very legitimacy of the state.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The genius of our ruling class is that it has kept a majority of the people from ever questioning the inequity of a system where most people drudge along, paying heavy taxes for which they get nothing in return ...", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "There is only one party in the United States, the Property party… and it has two right wings: Republican and Democrat. Republicans are a bit stupider, more rigid, more doctrinaire in their laissez-faire capitalism than the Democrats, who are cuter, prettier, a bit more corrupt — until recently… and more willing than the Republicans to make small adjustments when the poor, the black, the anti-imperialists get out of hand. But, essentially, there is no difference between the two parties.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "As the age of television progresses the Reagans will be the rule, not the exception. To be perfect for television is all a President has to be these days.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Never pass up a chance to have sex or appear on television.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I say, they don't have to conspire, because they all think alike. The president of General Motors and the president of Chase Manhattan Bank really are not going to disagree much on anything, nor would the editor of the New York Times disagree with them. They all tend to think quite alike, otherwise they would not be in those jobs.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Precocious talents mature slowly if at all.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "It is reasonable to assume that, by and large, what is not read now will not be read, ever. It is also reasonable to assume that practically nothing that is read now will be read later. Finally, it is not too farfetched to imagine a future in which novels are not read at all.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "In any case, write what you know will always be excellent advice to those who ought not to write at all.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Television is a great leveler. You always end up sounding like the people who ask the questions.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Religions are manipulated in order to serve those who govern society and not the other way around.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Actually, there is no such thing as a homosexual person, any more than there is such a thing as a heterosexual person. The words are adjectives describing sexual acts, not people. The sexual acts are entirely normal; if they were not, no one would perform them.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The reason no one has yet been able to come up with a good word to describe the homosexualist (sometimes known as gay, fag, queer, etc.) is because he does not exist. The human race is divided into male and female. Many human beings enjoy sexual relations with their own sex, many don't; many respond to both. This plurality is the fact of our nature and not worth fretting about.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "My father had a deep and lifelong contempt for politicians in general (\"They tell lies,\" he used to say with wonder, \"even when they don't have to\").", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The last best hope on earth, two trillion dollars in debt, is spinning out of control, and all we can do is stare at a flickering cathode-ray tube as Ollie \"answers\" questions on TV while the press, resolutely irrelevant as ever, asks politicians if they have committed adultery. From V-J Day 1945 to this has been, my fellow countrymen, a perfect nightmare.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "In a nation that has developed to a high art advertising, the creator who refuses to advertise himself is immediately suspected of having no product worth selling.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The average \"educated\" American has been made to believe that, somehow, the United States must lead the world even though hardly anyone has any information at all about those countries we are meant to lead. Worse, we have very little information about our own country and its past. That is why it is not really possible to compare a writer like Howells with any living American writer because Howells thought that it was a good thing to know as much as possible about his own country as well as other countries while our writers today, in common with the presidents and paint manufacturers, live in a present without past among signs whose meanings are uninterpretable.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I suspect that one of the reasons we create fiction is to make sex exciting.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Class is the most difficult subject for American writers to deal with as it is the most difficult for the English to avoid.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I regard monotheism as the greatest disaster ever to befall the human race. I see no good in Judaism, Christianity, or Islam — good people, yes, but any religion based on a single... well, frenzied and virulent god, is not as useful to the human race as, say, Confucianism, which is not a religion but an ethical and educational system that has worked pretty well for twenty-five hundred years. So you see I am ecumenical in my dislike for the Book. But like it or not, the Book is there; and because of it people die; and the world is in danger.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The great unmentionable evil at the center of our culture is monotheism. From a barbaric Bronze Age text known as the Old Testament, three anti-human religions have evolved — Judaism, Christianity, Islam. These are sky-god religions. They are, literally, patriarchal — God is the Omnipotent Father — hence the loathing of women for 2,000 years in those countries afflicted by the sky-god and his earthly male delegates. The sky-god is a jealous god, of course. He requires total obedience from everyone on earth, as he is in place not for just one tribe but for all creation. Those who would reject him must be converted or killed for their own good. Ultimately, totalitarianism is the only sort of politics that can truly serve the sky-god's purpose.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "'Liberal' comes from the Latin liberalis, which means pertaining to a free man. In politics, to be liberal is to want to extend democracy through change and reform. One can see why the word had to be erased from our political lexicon.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "At least when the Emperor Justinian, a sky-god man, decided to outlaw sodomy, he had to come up with a good practical reason, which he did. It is well known, Justinian declared, that buggery is a principal cause of earthquakes, and so must be prohibited. But our sky-godders, always eager to hate, still quote Leviticus, as if that looney text had anything useful to say about anything except, perhaps, the inadvisability of eating shellfish in the Jerusalem area.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "A current pejorative adjective is narcissistic. Generally, a narcissist is anyone better looking than you are, but lately the adjective is often applied to those “liberals” who prefer to improve the lives of others rather than exploit them. Apparently, a concern for others is self-love at its least attractive, while greed is now a sign of the highest altruism. But then to reverse, periodically, the meanings of words is a very small price to pay for our vast freedom not only to conform but to consume.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Apparently, a democracy is a place where numerous elections are held at great cost without issues and with interchangeable candidates.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Think of the earth as a living organism that is being attacked by billions of bacteria whose numbers double every forty years. Either the host dies, or the virus dies, or both die.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The corporate grip on opinion in the United States is one of the wonders of the Western World. No First World country has ever managed to eliminate so entirely from its media all objectivity — much less dissent.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "To speak today of a famous novelist is like speaking of a famous cabinetmaker or speedboat designer. Adjective is inappropriate to noun.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Half the American people never read a newspaper. Half never vote for President — the same half?", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Lonely children often have imaginary playmates but I was never lonely; rather, I was solitary, and wanted no company at all other than books and movies, and my own imagination.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Apparently, a concern for others is self-love at its least attractive, while greed is now a sign of the higher altruism. But then to reverse, periodically, the meanings of words is a very small price to pay for the freedom not only to conform but to consume.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I shared, naturally, in that hatred of organized labor which has been the one political constant in my lifetime, culminating in Ronald Reagan's most popular gesture, the smashing of the air-controllers' union. No alternative view of organized labor has ever come to us through the popular media. If labor leaders were not crooks like Jimmy Hoffa, they were in the pay of Moscow.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "It is notable how little empathy is cultivated or valued in our society. I put this down to our traditional racism and obsessive sectarianism. Even so, one would think that we would be encouraged to project ourselves into the character of someone of a different race or class, if only to be able to control him. But no effort is made.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "By and large, serious fiction was the work of victims who portrayed victims for an audience of victims who, it was oddly assumed, would want to see their lives realistically portrayed.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Every four years the naive half who vote are encouraged to believe that if we can elect a really nice man or woman President everything will be all right. But it won't be. Any individual who is able to raise $25 million to be considered presidential is not going to be much use to the people at large. He will represent oil, or aerospace, or banking, or whatever moneyed entities are paying for him. Certainly he will never represent the people of the country, and they know it. Hence, the sense of despair throughout the land as incomes fall, businesses fail and there is no redress.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "As societies grow decadent, the language grows decadent, too. Words are used to disguise, not to illuminate, action: you liberate a city by destroying it. Words are to confuse, so that at election time people will solemnly vote against their own interests.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Must one have a heart of stone to read The Ballad of Reading Gaol without laughing? (In life, practically no one ever gets to kill the thing he hates, much less loves.) And did not De Profundis plumb for all time the shallows of the most reported love affair of the past hundred years, rivalling even that of Wallis and David, its every nuance (O Bosie!) known to all, while trembling rosy lips yet form, over and over again, those doom-laden syllables The Cadogan Hotel? Oscar Wilde. Yet again. Why?", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "American society, literary or lay, tends to be humorless. What other culture could have produced someone like Hemingway and not seen the joke?", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We do not, of course, write literary criticism at all now. Academe has won the battle in which Wilson fought so fiercely on the other side. Ambitious English teachers now invent systems that have nothing to do with literature or life but everything to do with those games that must be played in order for them to rise in the academic bureaucracy. Their works are empty indeed. But then, their works are not meant to be full. They are to be taught, not read. The long dialogue has broken down. Fortunately, as Flaubert pointed out, the worst thing about the present is the future. One day there will be no... But I have been asked not to give the game away. Meanwhile, I shall drop a single hint: Only construct!", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "After four centuries, Montaigne's curious genius still has that effect on his readers and, time and again, one finds in his self-portrait one's own most brilliant aperçus (the ones that somehow we forgot to write down and so forgot) restored to us in his essays—attempts—to assay—value—himself in his own time as well as, if he was on the subject, all time, if there is such a thing.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "World events are the work of individuals whose motives are often frivolous, even casual.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The late Mr. [Carl] Sandburg was a public performer of the first rank (\"Ker-oh-seen!\" he crooned in one of the first TV pitches for the jet-engine — ole banjo on his knee, white hair mussed by the jet-stream), a poet of the second rank (who can ever forget that feline-footed fog?) and a biographer of awesome badness.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "In fact, the French - who read and theorise the most - became so addicted to political experiment that in the two centuries since our own rather drab revolution they have exuberantly produced one Directory, one Consulate, two empires, three restorations of the monarchy, and five republics. That's what happens when you take writing too seriously.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Professor Richard N. Current fusses, not irrelevantly, about the propriety of fictionalising actual political figures. I also fuss about this. But he has fallen prey to the scholar-squirrel's delusion that there is a final Truth revealed only to the tenured few in their footnote maze; in this he is simply naïve.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Current is also outraged by a reference to Lincoln's bowels, whose 'frequency,' he tells us, 'cannot be documented.' But, of course, they can. 'Truth-teller' Herndon tells us that Lincoln was chronically constipated and depended on a laxative called bluemass. Since saints do not have bowels, Current finds all this sacrilegious; hence 'wrong.'", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "What is going on here is a deliberate revision by Current not only of Lincoln but of himself in order to serve the saint in the 1980s as opposed to the saint at earlier times when black were still colored, having only just stopped being Negroes. In colored and Negro days the saint might have wanted them out of the country, as he did. But in the age of Martin Luther King even the most covertly racist of school boards must agree that a saint like Abraham Lincoln could never have wanted a single black person to leave freedom's land much less bravery's home. So all the hagiographers are redoing their plaster images and anyone who draws attention to the discrepancy between their own past crudities and their current falsities is a very bad person indeed, and not a scholar, and probably a communist as well.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Basler finds my ''Lincoln'' the 'phoniest historical novel I have ever had the pleasure of reading.'... Also, 'more than half the book could never have happened as told.' Unfortunately, he doesn't say which half. If I knew, we could then cut it free from the phony half and publish the result as Basler's Vidal's ''Lincoln''.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Nothing that Shakespeare ever invented was to equal Lincoln's invention of himself and, in the process, us.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I have begun writing what I have said I'd never write, a memoir (\"I am not my own subject,\" I used to say with icy superiority).", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Anais Nin gave me my most original, or so I thought, creation. As I read Incest, I realized that something which I had always taken to be unique, the voice of Myra Breckinridge, was actually that of Anaïs in all the flowing megalomania of the diaries. Of course, I had not read the diaries then, but even so, if only for that one thundering voice, I am forever in her debt.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I used to be able to summon up scenes at will, but now aging memory is so busy weeding its own garden that, promiscuously, it pulls up roses as well as crabgrass.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Celebrities are invariably celebrity-mad, just as liars always believe liars.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We're supposed to procreate and society, god knows, is ferocious on the subject. Heterosexuality is considered such a great and natural good that you have to execute people and put them in prison if they don't practice this glorious act.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We should stop going around babbling about how we're the greatest democracy on earth, when we're not even a democracy. We are a sort of militarised republic. The founding fathers hated two things, one was monarchy and the other was democracy, they gave us a constitution that saw to it we will have neither. I don't know how wise they were.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "One year after 9/11, we still don't know by whom we were struck that infamous Tuesday, or for what true purpose. But it is fairly plain to many civil-libertarians that 9/11 applied not only to much of our fragile Bill of Rights but also to our once-envied system of government which had taken a mortal blow the previous year when the Supreme Court did a little dance in 5/4 time and replaced a popularly elected president with the oil and gas Cheney/Bush junta.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Apparently, \"conspiracy stuff\" is now shorthand for unspeakable truth.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Post-9/11, the American media were filled with pre-emptory denunciations of unpatriotic 'conspiracy theorists', who not only are always with us but are usually easy for the media to discredit since it is an article of faith that there are no conspiracies in American life.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Happily for the busy lunatics who rule over us, we are permanently the United States of Amnesia. We learn nothing because we remember nothing.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We have ceased to be a nation under law but instead a homeland where the withered Bill of Rights, like a dead trumpet vine, clings to our pseudo-Roman columns.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Lennon was somebody who was a born enemy of those who govern the United States. He was everything they hated. So I just say that he represented life, and is admirable; and Mr. Nixon and Mr. Bush represent death, and that is a bad thing.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Private lives should be no business of the State. The State is bad enough as it is. It cannot educate or medicate or feed the people; it cannot do anything but kill the people. No State like that do we want prying into our private lives.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "History is nothing but gossip about the past, with the hope that it might be true.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I'm not a conspiracy theorist - I'm a conspiracy analyst.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We must always remember that the police are recruited from the criminal classes.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Don’t ever make the mistake with people like me thinking we are looking for heroes. There aren’t any and if there were, they would be killed immediately. I’m never surprised by bad behaviour. I expect it.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "You hear all this whining going on, \"Where are our great writers?\" The thing I might feel doleful about is: Where are the readers?", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Everything's wrong on Wikipedia.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "I never gave him any advice, and he never asked for any. We agreed on nothing, but we never quarreled once.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Nonprofit status is what created the Bible Belt. The tax code brought religion back to this country.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Patriotism is as sickening today as it has ever been. I was watching the news before you came and there was a lot of coverage of Kosovo and the problems there. They showed footage of people burning an American flag. And the newscaster got all broken up and teary-eyed. He says, \"I guess [sob] I just feel something here, folks, when I see the American flag being burned.\" And I said, You fucking asshole.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "People in my situation get to read about themselves whether they want to or not. It's generally wrong. Or oversimplified — which is sometimes useful.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We're the most captive nation of slaves that ever came along. The moral timidity of the average American is quite noticeable. Everybody's afraid to be thought in any way different from everyone else.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "You cannot get through the density of the propaganda with which the American people, through the dreaded media, have been filled and the horrible public educational system we have for the average person. It's just grotesque.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Well, it's been the monopolizing of great wealth, which tends to happen in basically unjust societies and undemocratic societies. We have plenty of would-be democrats, would-be liberals, and would-be progressives. But how do you organize? The Democratic Party is a machine to get votes for its people, none of who should probably be elected to the high offices of state. That's all. The Republican Party is fundamentally crooked and might well be outlawed one of these days.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "You think of the Republican Party as a party, like the British Conservative Party - well it isn't! I don't say that the British Conservative Party is much better, I'm only saying the Republican Party is a mindset. They love war! They love money! They're out to hang on through all the connections that they have, through their various operatives.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The founding fathers were not interested in democracy, in fact, in a country with 3 1/4 million people, which is about what we were at the time of the separation from England, only 700,000 people could vote — white males of property. So it's never been terribly democratic. ...and they put together a constitution which would protect property for all time. No nonsense about democracy!", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "For reasons that I leave to a higher psychiatry, Jr. wanted a war in Iraq. ...Jr. is really pretty vague, you know. He just wanted to go... \"Bang! Bang! Bang! Bang! Bang! Bang! Bang! We gotta stand tall, ya know? We can't cut and run, yeah, ya know what I mean.\" We've had bad presidents in the past, but we've never had a G-- D--d fool!", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "They already had contingency plans ready in case of terrorism, violence, whatever, which they had inherited from Clinton, who had put together some terrible legislation after Timothy McVeigh blew up the building in Oklahoma City.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "It was ready-made for them to call an emergency and pretend it was war-time, you know, the war on terrorism is a metaphor, and terrorism is an abstract noun. It's like a \"war on dandruff.\" There's no such thing, you know. It isn't war, it's just a slogan. But using the slogan they got through the U.S.A. Patriot Act, which removes many of our liberties. Nobody made a sound when we lost Habeas Corpus—due process of law—and suddenly Bush managed to get rid of it. Where was a voice on television, aside from mine, that spoke out against this? Where were all those noble jurists, those great lawyers, those lovers of liberty, where the hell were they? They were nowhere!", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Now we have a totalitarian government. And the totalitarian government wants to watch everybody, total surveillance of everyone. They listen to the telephone conversations, they look at your credit cards, they look where you travel. We are totally policed. This is contrary to everything in our Constitution.", Author = "Gore Vidal" },
        };
    }
}